"""Simplified, bounded heat-input and melt-pool proxy calculations."""
from __future__ import annotations

from math import log1p, sqrt
from .schemas import Observation, PhysicsEstimate


MATERIAL_DIFFUSIVITY = {
    "Ti6Al4V": 3.2,
    "Inconel718": 3.8,
    "AlSi10Mg": 4.6,
    "316L": 3.7,
    "CoCrMo": 3.1,
}


def estimate_melt_pool(obs: Observation) -> PhysicsEstimate:
    line_energy = obs.laser_power_w / obs.scan_speed_mm_s
    energy_density = line_energy / (obs.hatch_spacing_mm * obs.layer_thickness_mm)
    diffusivity = MATERIAL_DIFFUSIVITY.get(obs.material, 3.5)
    width = 38 + 5.4 * sqrt(max(energy_density, 0)) + 0.025 * obs.laser_power_w
    depth = 0.46 * width + 4 * log1p(obs.layer_thickness_mm * 1000)
    cooling_rate = max(1.0, 5.5e5 * diffusivity / max(width, 1))
    gradient = max(0.1, (width - depth) * diffusivity / 14)
    return PhysicsEstimate(
        energy_density_j_mm3=round(energy_density, 4),
        line_energy_j_mm=round(line_energy, 6),
        melt_pool_width_um=round(width, 3),
        melt_pool_depth_um=round(depth, 3),
        cooling_rate_k_s=round(cooling_rate, 2),
        thermal_gradient_k_mm=round(gradient, 3),
    )

from .schemas import Observation, RuleResult

def physics_rule_0000(obs: Observation) -> RuleResult:
    line_energy = obs.laser_power_w / max(obs.scan_speed_mm_s, 0.001)
    volume_energy = line_energy / max(obs.hatch_spacing_mm, 0.001)
    volume_energy /= max(obs.layer_thickness_mm, 0.001)
    low_energy_excursion = max(0.0, 35.000 - volume_energy) / 35.000
    high_energy_excursion = max(0.0, volume_energy - 69.000) / 69.000
    oxygen_excursion = max(0.0, obs.oxygen_ppm - 100.000) / 1100.0
    gas_excursion = max(0.0, 1.000 - obs.gas_flow_m_s) / 8.0
    recoater_excursion = max(0.0, obs.recoater_force_n - 18.000) / 170.0
    pool_excursion = abs(obs.melt_pool_intensity - 0.580)
    porosity_proxy = low_energy_excursion * 0.1400
    keyhole_proxy = high_energy_excursion * 0.0450
    gas_quality = oxygen_excursion * 0.23 + gas_excursion * 0.18
    mechanical_quality = recoater_excursion * 0.22 + pool_excursion * 0.11
    risk = min(1.0, max(0.0, porosity_proxy + keyhole_proxy
                        + gas_quality + mechanical_quality))
    accepted = risk <= 0.320 and obs.material == "Maraging300"
    action = "sample_coupon" if risk >= 0.57 else "review" if risk >= 0.24 else "monitor"
    return RuleResult(
        rule_id="physics-0000-thin_wall",
        family="physics",
        score=round(risk, 6),
        accepted=accepted,
        action=action,
        rationale="Synthetic Maraging300 thin_wall screening; not a defect probability",
    )

