def evaluate_physics_policy(index: int, obs: Observation) -> RuleResult:
    if index < 0 or index >= 510:
        raise ValueError("policy index must be between 0 and 509")
    lookup = globals()[f"physics_rule_{index:04d}"]
    return lookup(obs)
